    /** Texto no idioma do usuário, com {marcadores}. */
    public static function t(string $chave, array $valores = []): string
    {
        $d = self::TEXTOS[$chave] ?? self::EXTRA[$chave] ?? [$chave, $chave, $chave];
        return IdiomaService::f(self::GRUPO . '.' . $chave, ['pt' => $d[0], 'en' => $d[1], 'es' => $d[2]], $valores);
    }

    /** Valores gravados como texto (situação e "devido" da lei): o banco guarda em português; a tela mostra traduzido. */
    private const VALORES = ['Lei Inclusa' => 'valor.lei_inclusa', 'Lei Alterada' => 'valor.lei_alterada', 'Lei Revogada' => 'valor.lei_revogada',
        'Devido à Atualização' => 'valor.devido_atualizacao', 'Devido ao Ajuste' => 'valor.devido_ajuste', 'Alterada pela Atualização' => 'valor.alterada_atualizacao',
        'Alterada pelo Ajuste' => 'valor.alterada_ajuste', 'Retirado pela Atualização' => 'valor.retirado_atualizacao'];

    public static function valor(string $v): string
    {
        return isset(self::VALORES[$v]) ? self::t(self::VALORES[$v]) : $v;
    }

    /** [valor gravado => texto traduzido] dos valores conhecidos (para o JavaScript do grid). */
    public static function valores(): array
    {
        $out = [];
        foreach (self::VALORES as $v => $k) $out[$v] = self::t($k);
        return $out;
    }

    /** Chaves usadas pelo JavaScript, no formato de IdiomaService::script (chave completa => [pt, en, es]). */
    public static function js(): array
    {
        $out = [];
        foreach (self::JS as $k => $d) $out[self::GRUPO . '.' . $k] = ['pt' => $d[0], 'en' => $d[1], 'es' => $d[2]];
        return $out;
    }

