        'filhas.vazio_esquerda' => ['Nenhuma lei com esse filtro. Em Sugeridas, troque para Todas.', 'No laws with this filter. In Suggested, switch to All.', 'Ninguna ley con este filtro. En Sugeridas, cambie a Todas.'],
        'filhas.vazio_direita' => ['Nenhuma lei filha. Marque à esquerda e use ›.', 'No child laws. Tick on the left and use ›.', 'Ninguna ley hija. Marque a la izquierda y use ›.'],
        'assuntos.titulo' => ['Assuntos da legislação', 'Legislation subjects', 'Asuntos de la legislación'],
        'assuntos.msg_vinculados' => ['{n} assunto(s) vinculado(s).', '{n} subject(s) linked.', '{n} asunto(s) vinculado(s).'],
        'assuntos.msg_retirados' => ['{n} assunto(s) retirado(s) da lei (continuam no catálogo).', '{n} subject(s) removed from the law (they remain in the catalog).', '{n} asunto(s) retirado(s) de la ley (siguen en el catálogo).'],
        'assuntos.explica' => ['À esquerda, o catálogo de assuntos (busca por texto ou código); à direita, os assuntos desta lei. Marque e use › para vincular ou ‹ para tirar — o assunto continua no catálogo. Vale para todas as empresas.', 'On the left, the subject catalog (search by text or code); on the right, the subjects of this law. Tick and use › to link or ‹ to remove — the subject stays in the catalog. Applies to all companies.', 'A la izquierda, el catálogo de asuntos (búsqueda por texto o código); a la derecha, los asuntos de esta ley. Marque y use › para vincular o ‹ para quitar — el asunto sigue en el catálogo. Vale para todas las empresas.'],
