        'pal.msg_nova' => ['Palavra-chave incluída no catálogo e vinculada.', 'Keyword added to the catalog and linked.', 'Palabra clave incluida en el catálogo y vinculada.'],
        'pal.msg_existia_vinculada' => ['Essa palavra-chave já existia no catálogo (código {cod}) e foi vinculada.', 'This keyword already existed in the catalog (code {cod}) and was linked.', 'Esta palabra clave ya existía en el catálogo (código {cod}) y fue vinculada.'],
        'pal.msg_existia_ja' => ['Essa palavra-chave já existia no catálogo (código {cod}) e já estava vinculada a esta lei.', 'This keyword already existed in the catalog (code {cod}) and was already linked to this law.', 'Esta palabra clave ya existía en el catálogo (código {cod}) y ya estaba vinculada a esta ley.'],
        'chk.msg_nova' => ['Pergunta incluída no catálogo e vinculada.', 'Question added to the catalog and linked.', 'Pregunta incluida en el catálogo y vinculada.'],
        'chk.msg_editado' => ['Texto alterado no catálogo (vale para {n} lei(s)).', 'Text changed in the catalog (applies to {n} law(s)).', 'Texto modificado en el catálogo (vale para {n} ley(es)).'],
        'pal.msg_editado' => ['Texto alterado no catálogo (vale para {n} lei(s) e para as licenças que usam a palavra).', 'Text changed in the catalog (applies to {n} law(s) and to the licenses that use the keyword).', 'Texto modificado en el catálogo (vale para {n} ley(es) y para las licencias que usan la palabra).'],
        'pal.msg_ia_incluidas' => ['{n} palavra(s)-chave vinculada(s).', '{n} keyword(s) linked.', '{n} palabra(s) clave vinculada(s).'],
        'pal.msg_ia_novas' => ['{n} nova(s) no catálogo', '{n} new in the catalog', '{n} nueva(s) en el catálogo'],
