        'chk.copiar_dica' => ['Escolha a lei de origem. Só entram as perguntas que esta lei ainda não tem; nada é apagado.', 'Choose the source law. Only questions this law does not have yet are added; nothing is deleted.', 'Elija la ley de origen. Solo entran las preguntas que esta ley aún no tiene; no se borra nada.'],
        'chk.copiar_btn' => ['Copiar', 'Copy', 'Copiar'],
        'pal.ia_titulo' => ['Palavras-chave sugeridas pela IA', 'Keywords suggested by the AI', 'Palabras clave sugeridas por la IA'],
        'pal.ia_dica' => ['Marque as que quer vincular. As "novas" entram no catálogo.', 'Tick the ones you want to link. The "new" ones are added to the catalog.', 'Marque las que quiere vincular. Las "nuevas" entran en el catálogo.'],
