        'rcl.filtros' => ['Para gerar o RCL escolha Empresa, Unidade e Mês/Ano nos filtros da tela.', 'To generate the RCL, choose Company, Unit and Month/Year in the screen filters.', 'Para generar el RCL elija Empresa, Unidad y Mes/Año en los filtros de la pantalla.'],
